public class LruCache
{
    private class Node
    {
        public int Key;
        public int Value;
        public Node? Prev;
        public Node? Next;
    }

    private readonly int _capacity;
    private readonly Dictionary<int, Node> _map = new();

    // Sentinels: _head.Next is most recent, _tail.Prev is least recent.
    // Using sentinels means we never have to special-case an empty list.
    private readonly Node _head = new();
    private readonly Node _tail = new();

    public LruCache(int capacity)
    {
        _capacity = capacity;
        _head.Next = _tail;
        _tail.Prev = _head;
    }

    public int Get(int key)
    {
        if (!_map.TryGetValue(key, out var node)) return -1;

        MoveToFront(node);
        return node.Value;
    }

    public void Put(int key, int value)
    {
        if (_map.TryGetValue(key, out var existing))
        {
            existing.Value = value;
            MoveToFront(existing);
            return;
        }

        var node = new Node { Key = key, Value = value };
        _map[key] = node;
        AddToFront(node);

        if (_map.Count > _capacity)
        {
            var lru = _tail.Prev!;      // least recently used
            Remove(lru);
            _map.Remove(lru.Key);
        }
    }

    private void AddToFront(Node node)
    {
        node.Next = _head.Next;
        node.Prev = _head;
        _head.Next!.Prev = node;
        _head.Next = node;
    }

    private void Remove(Node node)
    {
        node.Prev!.Next = node.Next;
        node.Next!.Prev = node.Prev;
    }

    private void MoveToFront(Node node)
    {
        Remove(node);
        AddToFront(node);
    }
}

public class LruCache
{
    private class Node
    {
        public int Key, Value;
        public Node? Prev, Next;
    }

    private readonly int _capacity;
    private readonly Dictionary<int, Node> _map = new();
    private readonly Node _head = new();
    private readonly Node _tail = new();

    public LruCache(int capacity)
    {
        _capacity = capacity;
        _head.Next = _tail;
        _tail.Prev = _head;
    }

    public int Get(int key)
    {
        if (!_map.TryGetValue(key, out var node)) return -1;
        MoveToFront(node);
        return node.Value;
    }

    public void Put(int key, int value)
    {
        if (_map.TryGetValue(key, out var existing))
        {
            existing.Value = value;
            MoveToFront(existing);
            return;
        }

        var node = new Node { Key = key, Value = value };
        _map[key] = node;
        AddToFront(node);

        if (_map.Count > _capacity)
        {
            var lru = _tail.Prev!;
            Remove(lru);
            _map.Remove(lru.Key);
        }
    }

    private void AddToFront(Node n)
    {
        n.Next = _head.Next;
        n.Prev = _head;
        _head.Next!.Prev = n;
        _head.Next = n;
    }

    private void Remove(Node n)
    {
        n.Prev!.Next = n.Next;
        n.Next!.Prev = n.Prev;
    }

    private void MoveToFront(Node n)
    {
        Remove(n);
        AddToFront(n);
    }
}
